Fixpoint evars_ok (ok : nat -> bool) (e : expr) : bool :=
  match e with
  | ELit _ => true
  | EVar n => ok n
  | EAlu _ x y | EAluw _ x y | EMd _ x y | EMdw _ x y => evars_ok ok x && evars_ok ok y
  | EExt _ _ _ x => evars_ok ok x
  | EBlob _ _ _ _ => true
  end.
