End ThrowCore.

Section ThrowCorePool.
Context {HCEIL : HeapCeil.HeapCeil}.
Hypothesis C : ltac2:(zQ "10!kpa$0").
Hypothesis F : ltac2:(zQ "10!kq7$0").
Variable CATCHd : ltac2:(zQ "10!kv6$0").
Variables (G' : list frame) (f1 : frame) (E0 : env) (R0 : bvmap 5 word) (M00 : word -> option byte).
Variable steady : bool.   (* [comment removed for export] *)
Variable pidle : bool.    (* [comment removed for export] *)
Let pool : pool_state := if pidle then PoolIdle else PoolPristine.
Let G := f1 :: G'.
Let A : Z := bv_unsigned (ev E0 0%nat).
Let Hd : Z := POOLHDR.
Let spN : Z := fr_sp (lastf G CATCHd).
(* [comment removed for export] *)
Hypothesis HINV0 : INV EhX_plain.SEGS E0 (SS 0x94c68 (F2_regs (lit 0)) [] (TH_T steady 0 pool) NX) [] R0 M00.
Hypothesis Hch1 : forall Θ, Θ 0%nat = ev E0 0%nat -> chainT stof Θ M00 midP1 G.
Hypothesis Hch2 : forall Θ, Θ 0%nat = ev E0 0%nat -> chainT2 stof Θ M00 midP2 1856 G.
Hypothesis Hsp1 : fr_sp f1 = A + 1856.
Hypothesis Hret : ltac2:(zQ "70!h4!l6!it4!llb!lq8!tf!is1@3$0$2@2$6@1$1#k0@2$5?2E0No4@1$3@1$4?2f1").
Hypothesis Hlive : ltac2:(zQ "80!j7!h4!ls2!ltd!l6!mi6!tf!na>1k$0>0@2$3^1N8@3$1@1$7@1$4#k0@2$6?2E0@2$2Nnc^2@2$5?2f1^2").
Hypothesis Hlive8 : ltac2:(zQ "b0!j7!isf!h4!ls2!mie!mj5!ltd!l6!mi6!tf!na>1k$0>0@2$1@2$5N8^1@2$6^1Nc@3$2@1$a@1$7#k0@2$9?2E0@2$3Nh4@2$4^2N8@2$8?2f1^2").
Hypothesis A_lo : 0x400000000000 <= A + ZLO.
Hypothesis H_low : Hd + 144 <= A + ZLO.

Theorem throw_core_pool : forall fx : FPState,
  exists (fx' : FPState) E' R' M' t,
